import assert from 'node:assert/strict';
import path from 'node:path';

// Small same-instance smoke after the timed replay, using actual browser input.
// Detailed clipped/skinned silhouette regressions remain in the existing
// cs2-viewmodel-browser test; this does not duplicate that complete suite.
export async function runProductionWeaponSmoke({page,server,artifactRoot}){
  const id=await page.evaluate(()=>window.lanStrike.getId()),player=server.game.players.get(id),result={checks:[],weapons:[]};assert.ok(player);
  async function lock(){if(!await page.evaluate(()=>document.pointerLockElement===document.querySelector('#game'))){await page.locator('#resumeButton').click();await page.waitForFunction(()=>document.pointerLockElement===document.querySelector('#game')&&document.hasFocus(),undefined,{timeout:8000});}}
  async function prepare(weapon){
    player.team=weapon==='aug'?'CT':'T';player.character=player.team==='CT'?'urban':'terror';const g=server.game;g.begin();g.phase='live';g.endAt=g.time+10000;g.buyEndAt=g.time+10000;player.money=16000;
    if(weapon!=='knife'&&!player.inventory[weapon])g.buy(id,weapon);g.equip(id,weapon);g.drops=[];server.broadcastState();await lock();await page.waitForFunction(({weapon,round})=>{const s=window.lanStrike,d=s.getDiagnostics();return s.getState()?.round===round&&d.weapon===weapon&&d.weaponModel.id===weapon&&d.weaponModel.source==='source2-native-gltf'&&!d.weaponModel.loading&&d.weaponModel.sequence==='idle';},{weapon,round:g.round},{timeout:15000});
    const d=await page.evaluate(()=>window.lanStrike.getDiagnostics());assert.equal(d.weaponModel.error,null);return d;
  }
  async function visibleWeapon(){return page.evaluate(async()=>{const THREE=await import('/vendor/three.module.js'),c=window.__pointerTrace.refs,root=c.worldCamera.getObjectByName('source2-native-viewmodel'),group=root?.parent,camera=c.viewmodelCamera;let visible=!!root;for(let o=root;o;o=o.parent)visible&&=o.visible;assertLocal(visible&&camera,'Native foreground must be visible');root.updateWorldMatrix(true,true);camera.updateWorldMatrix(true,false);const socket=root.children[0]?.getObjectByName('wpn'),weapons=socket?.children.filter(o=>o.getObjectByName('weapon'))||[],point=new THREE.Vector3();let samples=0,inFrustum=0,skinnedMeshes=0;for(const w of weapons)w.traverse(mesh=>{if(!mesh.isSkinnedMesh||!mesh.geometry?.attributes.position)return;skinnedMeshes++;for(let i=0;i<mesh.geometry.attributes.position.count;i+=8){mesh.getVertexPosition(i,point);point.applyMatrix4(mesh.matrixWorld).project(camera);samples++;if(point.z>=-1&&point.z<=1&&Math.abs(point.x)<=1&&Math.abs(point.y)<=1)inFrustum++;}});return{visible,weaponRoots:weapons.length,skinnedMeshes,samples,inFrustum,groupPosition:group.position.toArray()};function assertLocal(ok,message){if(!ok)throw Error(message);}});}
  await prepare('knife');const knife=await visibleWeapon();assert.equal(knife.weaponRoots,1);assert.ok(knife.skinnedMeshes>0&&knife.inFrustum>=3,'Actual skinned knife vertices must reach the viewmodel frustum');result.knife=knife;result.checks.push('native knife group and skinned weapon vertices are visible');
  await page.screenshot({path:path.join(artifactRoot,'production-knife.png')});
  for(const weapon of ['aug','sg552']){
    const hip=await prepare(weapon);await page.mouse.click(960,418,{button:'right'});await page.waitForFunction(()=>{const d=window.lanStrike.getDiagnostics();return d.weaponModel.sequence==='zoomIdle'&&d.weaponModel.ads?.amount>.98;},undefined,{timeout:8000});const ads=await page.evaluate(()=>({model:window.lanStrike.getDiagnostics().weaponModel,scopeOverlay:document.querySelector('#scopeOverlay').hidden}));assert.ok(ads.model.ads.lensMeshes>0&&ads.model.ads.reticle);assert.equal(ads.scopeOverlay,true);const geometry=await visibleWeapon();assert.ok(geometry.inFrustum>0);await page.screenshot({path:path.join(artifactRoot,'production-'+weapon+'-ads.png')});await page.waitForTimeout(350);await page.mouse.click(960,418,{button:'right'});await page.waitForFunction(()=>{const d=window.lanStrike.getDiagnostics();return d.weaponModel.sequence==='idle'&&d.weaponModel.ads?.amount<.01;},undefined,{timeout:8000});result.weapons.push({weapon,hip:{id:hip.weaponModel.id,sequence:hip.weaponModel.sequence},ads,geometry});
  }
  result.checks.push('AUG/SG actual secondary input enters and exits native lens ADS');
  await prepare('awp');const sidearm=player.pistol;await page.keyboard.press('2');await page.waitForFunction(weapon=>window.lanStrike.getDiagnostics().weapon===weapon,sidearm);await page.keyboard.press('1');await page.waitForFunction(()=>window.lanStrike.getDiagnostics().weapon==='awp'&&window.lanStrike.getDiagnostics().weaponModel.id==='awp');assert.equal(player.previousWeapon,sidearm);
  await page.keyboard.press('q');await page.waitForFunction(weapon=>window.lanStrike.getDiagnostics().weapon===weapon,sidearm);await page.keyboard.press('q');await page.waitForFunction(()=>{const d=window.lanStrike.getDiagnostics();return d.weapon==='awp'&&d.weaponModel.id==='awp'&&!d.weaponModel.loading&&d.weaponModel.sequence==='idle';},undefined,{timeout:8000});assert.equal(player.weapon,'awp');assert.equal(player.zoom,90);result.awp={weapon:player.weapon,previous:player.previousWeapon,geometry:await visibleWeapon()};result.checks.push('AWP actual 2/1 and rapid Q/Q switch away and back');
  await prepare('knife');const position={x:player.x,y:player.y,z:player.z},context=page.context(),input=await context.newCDPSession(page);await page.mouse.move(960,418);const before=await page.evaluate(()=>window.__pointerTrace.refs.readMotion().input);for(let n=1;n<=30;n++)await input.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:960+n*20,y:418,button:'none',buttons:0,pointerType:'mouse'});await input.detach();const after=await page.evaluate(()=>window.__pointerTrace.refs.readMotion().input);assert.ok(Math.abs((after.yaw-before.yaw)+600*.00035)<1e-8);assert.ok(Math.hypot(player.x-position.x,player.y-position.y,player.z-position.z)<1e-8);result.stationaryTurn={before,after,counts:600,position};result.checks.push('short trusted stationary turn preserves authority position and exact yaw counts');
  result.webglError=await page.evaluate(()=>window.__pointerTrace.refs.renderer.getContext().getError());assert.equal(result.webglError,0);assert.equal(await page.evaluate(()=>document.pointerLockElement===document.querySelector('#game')&&document.hasFocus()),true);return result;
}

export async function runProductionMovementSmoke({page,artifactRoot}){
  if(!await page.evaluate(()=>document.pointerLockElement===document.querySelector('#game'))){await page.locator('#resumeButton').click();await page.waitForFunction(()=>document.pointerLockElement===document.querySelector('#game')&&document.hasFocus(),undefined,{timeout:8000});}
  const before=await page.evaluate(()=>window.lanStrike.getDiagnostics());await page.keyboard.down('Space');await page.waitForFunction(y=>{const c=window.__pointerTrace.refs.readMotion();return !c.local.grounded&&c.local.y>y+.1;},before.localPosition.y,{timeout:5000});await page.keyboard.up('Space');await page.waitForFunction(()=>window.__pointerTrace.refs.readMotion().local.grounded,undefined,{timeout:5000});
  await page.keyboard.down('KeyC');await page.waitForFunction(()=>{const s=window.lanStrike,id=s.getId(),p=s.getState().players.find(p=>p.id===id);return p.duckAmount>.9;},undefined,{timeout:5000});const crouched=await page.evaluate(()=>window.lanStrike.getDiagnostics());assert.ok(crouched.cameraY<before.cameraY-.1);await page.keyboard.up('KeyC');await page.waitForFunction(y=>{const s=window.lanStrike,id=s.getId(),p=s.getState().players.find(p=>p.id===id);return p.duckAmount<.05&&s.getDiagnostics().cameraY>y-.05;},before.cameraY,{timeout:5000});
  const knife=await page.evaluate(async()=>{const THREE=await import('/vendor/three.module.js'),c=window.__pointerTrace.refs,root=c.worldCamera.getObjectByName('source2-native-viewmodel'),camera=c.viewmodelCamera;let visible=!!root;for(let o=root;o;o=o.parent)visible&&=o.visible;root.updateWorldMatrix(true,true);camera.updateWorldMatrix(true,false);const socket=root.children[0]?.getObjectByName('wpn'),weapons=socket?.children.filter(o=>o.getObjectByName('weapon'))||[],point=new THREE.Vector3();let inFrustum=0,skinnedMeshes=0;for(const w of weapons)w.traverse(mesh=>{if(!mesh.isSkinnedMesh||!mesh.geometry?.attributes.position)return;skinnedMeshes++;for(let i=0;i<mesh.geometry.attributes.position.count;i+=8){mesh.getVertexPosition(i,point);point.applyMatrix4(mesh.matrixWorld).project(camera);if(point.z>=-1&&point.z<=1&&Math.abs(point.x)<=1&&Math.abs(point.y)<=1)inFrustum++;}});return{visible,weaponRoots:weapons.length,skinnedMeshes,inFrustum};});assert.ok(knife.visible&&knife.weaponRoots===1&&knife.skinnedMeshes>0&&knife.inFrustum>=3);await page.screenshot({path:path.join(artifactRoot,'production-movement-smoke.png')});const error=await page.evaluate(()=>window.__pointerTrace.refs.renderer.getContext().getError());assert.equal(error,0);return{jumpLanded:true,crouchAndStand:true,knife,webglError:error};
}
